// An independent second read of the vendored options manifests
// (test/fixtures/option_manifests/*.json): checks them against the SDKs' SOURCE.
//
//   dart scripts/verify_option_manifests.dart \
//     --android-repo <android/sdk checkout> --android-ref v7.4.2 \
//     --ios-repo <ios/sdk checkout> --ios-ref origin/nextgen
//
// The manifests are generated by the SDKs from their live registries and are the
// authority (scripts/sync_option_manifests.dart); this exists to catch a manifest that
// does not describe the source it claims to, and to say so when the iOS source has moved
// past the pinned release. It reads files with `git show <ref>:<path>` and never switches
// branches in those repositories. It needs the (private) SDK checkouts, so it is a local
// check, not a CI step; the result of the last run is recorded in PLAN.md.
//
// What it compares, per platform:
//   * the set of public option keys declared in source == the manifest's non-hidden keys
//   * every manifest enum's `values` == the enum declared in source, by INTERNAL value
//   * the hidden keys the manifest lists == the `$$` keys the source registers
//
// Exit 1 on any difference. Dart SDK only.
import 'dart:convert';
import 'dart:io';

import 'extract_report_enums.dart' show javaIntEnum, stripComments;

const androidOptionFiles = [
  'library/src/main/java/com/bugsee/library/contracts/options/Options.java',
  'ndk/src/main/java/com/bugsee/library/contracts/options/NdkOptions.java',
  'leak/src/main/java/com/bugsee/library/contracts/options/LeakOptions.java',
];
const androidDescriptors =
    'library/src/main/java/com/bugsee/library/options/OptionsDescriptors.java';
const androidEnumDir =
    'library/src/main/java/com/bugsee/library/contracts/options';

const iosOptionKeysFile = 'BugseeDev/BugseeLib/BugseeLib/BugseeOptions.m';
const iosDescriptors = 'BugseeDev/BugseeLib/BugseeLib/BGSOptionsDescriptors.m';
const iosEnumFiles = [
  'BugseeDev/BugseeLib/BugseeLib/BugseeConstants.h',
  'BugseeDev/BugseeLib/BugseeLib/Interception/Log/BugseeLogger.h',
];

/// `String Name = "com.bugsee.option...";` declarations (Android), `$$` keys included.
Set<String> androidKeys(String source) => {
  for (final m in RegExp(
    r'String\s+\w+\s*=\s*"(com\.bugsee\.option\.[^"]+)"',
  ).allMatches(stripComments(source)))
    m.group(1)!,
};

/// `NSString *const X = @"com.bugsee.option...";` (iOS).
Set<String> iosKeys(String source) => {
  for (final m in RegExp(
    r'NSString\s*\*const\s+\w+\s*=\s*@"(com\.bugsee\.option\.[^"]+)"',
  ).allMatches(stripComments(source)))
    m.group(1)!,
};

/// The members of an Objective-C enum, by value, tolerating `NS_SWIFT_NAME(...)` and
/// implicit values.
Map<String, int> objcEnumValues(String source, String name) {
  final clean = stripComments(
    source,
  ).replaceAll(RegExp(r'NS_SWIFT_NAME\([^)]*\)'), '');
  final patterns = [
    RegExp(
      r'typedef\s+NS_(?:ENUM|OPTIONS)\s*\(\s*[\w ]+\s*,\s*' +
          name +
          r'\s*\)\s*\{([^}]*)\}',
    ),
    RegExp(
      r'typedef\s+enum\s*(?::\s*[\w ]+)?\s*\{([^}]*)\}\s*' + name + r'\s*;',
    ),
  ];
  for (final p in patterns) {
    final m = p.firstMatch(clean);
    if (m == null) continue;
    final out = <String, int>{};
    var next = 0;
    for (final entry in m.group(1)!.split(',')) {
      final e = RegExp(
        r'^\s*(\w+)\s*(?:=\s*(-?\d+)\s*)?$',
      ).firstMatch(entry.trim());
      if (e == null) continue;
      final value = e.group(2) == null ? next : int.parse(e.group(2)!);
      out[e.group(1)!] = value;
      next = value + 1;
    }
    return out;
  }
  throw FormatException('no enum $name');
}

String arg(List<String> args, String name) {
  final i = args.indexOf(name);
  if (i < 0 || i + 1 >= args.length) {
    stderr.writeln('missing $name');
    exit(2);
  }
  return args[i + 1];
}

String show(String repo, String ref, String path) {
  final r = Process.runSync('git', ['-C', repo, 'show', '$ref:$path']);
  if (r.exitCode != 0) {
    throw StateError('git show $ref:$path failed: ${r.stderr}');
  }
  return r.stdout as String;
}

Map<String, dynamic> manifest(String root, String sdk) =>
    jsonDecode(
          File(
            '$root/test/fixtures/option_manifests/$sdk.json',
          ).readAsStringSync(),
        )
        as Map<String, dynamic>;

List<String> compareKeys(
  String label,
  Map<String, dynamic> m,
  Set<String> sourceKeys,
  Set<String> sourceHidden,
) {
  final options = (m['options'] as List).cast<Map<String, dynamic>>();
  final publicKeys = {
    for (final o in options)
      if (o['hidden'] != true) o['key'] as String,
  };
  final hiddenKeys = {
    for (final o in options)
      if (o['hidden'] == true) o['key'] as String,
  };
  final problems = <String>[];
  for (final k in publicKeys.difference(sourceKeys)) {
    problems.add('$label: manifest lists $k, source does not declare it');
  }
  for (final k in sourceKeys.difference(publicKeys)) {
    problems.add('$label: source declares $k, the manifest does not list it');
  }
  for (final k in hiddenKeys.difference(sourceHidden)) {
    problems.add('$label: manifest hides $k, source does not register it');
  }
  for (final k in sourceHidden.difference(hiddenKeys)) {
    problems.add('$label: source registers hidden $k, manifest lacks it');
  }
  return problems;
}

List<String> compareEnums(
  String label,
  Map<String, dynamic> m,
  Map<String, Map<String, int>> sourceEnums,
) {
  final problems = <String>[];
  final seen = <String>{};
  for (final o in (m['options'] as List).cast<Map<String, dynamic>>()) {
    final e = o['enum'] as Map<String, dynamic>?;
    if (e == null) continue;
    final name = e['name'] as String;
    if (!seen.add(name)) continue;
    final source = sourceEnums[name];
    if (source == null) {
      // Not declared in a file this script reads (a string-valued enum, or one outside it).
      problems.add('$label: enum $name is not declared in the files read');
      continue;
    }
    final fromManifest = (e['values'] as Map).cast<String, Object?>();
    if (jsonEncode(
          Map.fromEntries(fromManifest.entries.toList()..sort(_byKey)),
        ) !=
        jsonEncode(Map.fromEntries(source.entries.toList()..sort(_byKey)))) {
      problems.add(
        '$label: enum $name: manifest $fromManifest != source $source',
      );
    }
  }
  return problems;
}

String _stripPrefix(String member, List<String> prefixes) {
  for (final p in prefixes) {
    if (member.startsWith(p)) return member.substring(p.length);
  }
  return member;
}

int _byKey(MapEntry<String, Object?> a, MapEntry<String, Object?> b) =>
    a.key.compareTo(b.key);

void main(List<String> args) {
  final root = File.fromUri(Platform.script).parent.parent.path;
  final androidRepo = arg(args, '--android-repo');
  final androidRef = arg(args, '--android-ref');
  final iosRepo = arg(args, '--ios-repo');
  final iosRef = arg(args, '--ios-ref');
  final problems = <String>[];

  // ---- Android
  final am = manifest(root, 'android');
  final aSources = [
    for (final f in androidOptionFiles) show(androidRepo, androidRef, f),
  ];
  final aDescriptors = show(androidRepo, androidRef, androidDescriptors);
  final aAll = aSources.expand(androidKeys).toSet();
  // The hidden options are registered by literal in the descriptors, not declared as constants.
  final aHidden = {
    for (final m in RegExp(
      r'"(com\.bugsee\.option\.\$\$\w+)"',
    ).allMatches(stripComments(aDescriptors)))
      m.group(1)!,
  };
  problems.addAll(
    compareKeys('android@$androidRef', am, aAll.difference(aHidden), aHidden),
  );
  final aEnums = <String, Map<String, int>>{};
  for (final name in [
    'LogLevel',
    'VideoMode',
    'VideoQuality',
    'FrameRate',
    'IssueSeverity',
  ]) {
    aEnums[name] = javaIntEnum(
      show(androidRepo, androidRef, '$androidEnumDir/$name.java'),
      name,
    );
  }
  // MemoryLeakMode carries a string; it is read by the extension module and only
  // checked for presence here.
  final problemsAndroid = compareEnums('android@$androidRef', am, aEnums)
    ..removeWhere((p) => p.contains('enum MemoryLeakMode'));
  problems.addAll(problemsAndroid);

  // ---- iOS
  final im = manifest(root, 'ios');
  final iKeys = iosKeys(show(iosRepo, iosRef, iosOptionKeysFile));
  final iHidden = iosKeys(
    show(iosRepo, iosRef, iosDescriptors),
  ).where((k) => k.startsWith('com.bugsee.option.\$\$')).toSet();
  problems.addAll(
    compareKeys('ios@$iosRef', im, iKeys.difference(iHidden), iHidden),
  );
  final iosSource = iosEnumFiles
      .map((f) => show(iosRepo, iosRef, f))
      .join('\n');
  final iEnums = <String, Map<String, int>>{};
  for (final name in [
    'BugseeSeverityLevel',
    'BugseeFrameRate',
    'BugseeVideoQuality',
    'BugseeStyle',
    'BugseeLogLevel',
    'BugseeDataEncryptionMode',
    'BugseeCrashHandlerType',
  ]) {
    // Members are `BugseeSeverityLow`-style: compare by the part after the type prefix, as
    // the manifest names them.
    final raw = objcEnumValues(iosSource, name);
    final prefixes = [
      name,
      if (name.endsWith('Mode')) name.substring(0, name.length - 4),
      if (name == 'BugseeSeverityLevel') 'BugseeSeverity',
    ];
    iEnums[name] = {
      for (final e in raw.entries)
        // `Invalid` is the SDK's internal "no level" member, not a settable value.
        if (e.key != '${name}Invalid') _stripPrefix(e.key, prefixes): e.value,
    };
  }
  problems.addAll(compareEnums('ios@$iosRef', im, iEnums));

  if (problems.isEmpty) {
    stdout.writeln(
      'manifests agree with source: android@$androidRef '
      '(${aAll.length} keys), ios@$iosRef (${iKeys.length} keys)',
    );
    return;
  }
  problems.forEach(stderr.writeln);
  exit(1);
}
